insert into public.web_proyectos (id, nombre, inmobiliaria, comuna, uf, entrega, dorm, m2, etiqueta, resumen, descripcion, datos, fotos, enlace, sitios, destacado, ejemplo, orden) values
  ('eco-florida', 'Eco Florida', 'Fundamenta', 'La Florida', 3730, 'inmediata', '{0,1,2}', '30 a 56 m²', '', 'Torre de 23 pisos a pasos de Metro Vicuña Mackenna y Mall Plaza Vespucio, con piscina, cowork y gimnasio.', '{"Eco Florida (Torre I) se ubica en Froilán Roa 1201, en el corazón comercial de La Florida, a pasos de la estación Vicuña Mackenna (L4 y L4A) y cerca de Bellavista de La Florida (L5). El entorno concentra Mall Plaza Vespucio, supermercados, clínicas y servicios, lo que lo hace atractivo para arriendo de larga y corta estadía.","Edificio de 23 pisos con studios, 1D1B y 2D2B de 30 a 56 m², con terminaciones Diseño Más (piso fotolaminado, mesón de granito, vitrocerámica). Los Espacios Más incluyen hall de doble altura, piscina al aire libre, jardín interior, BBQ panorámico, lounge TV, espacio gourmet, cowork, fitness y centro de lavado."}', '[["Dirección","Froilán Roa 1201, La Florida"],["Tipologías","Studio · 1D1B · 2D2B"],["Superficie","30 a 56 m²"],["Metro","Vicuña Mackenna (L4/L4A) y Bellavista de La Florida (L5)"],["Amenities","Piscina · BBQ panorámico · Cowork · Fitness · Lounge TV · Lavandería"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-florida-1.webp","alt":"Render fachada Eco Florida, La Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-florida-2.webp","alt":"Piscina al aire libre Eco Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-florida-3.webp","alt":"Cowork Eco Florida"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-la-florida/eco-florida/', '{"imobu","mdiaz"}', false, false, 0),
  ('eco-florida-ii', 'Eco Florida II', 'Fundamenta', 'La Florida', 2263, 'futura', '{0,1,2}', '29 a 32 m²', 'Entrega 2027', 'Segunda torre de Eco Florida junto a Metro Vicuña Mackenna: studios en verde con piscina, pet zone y cowork.', '{"Eco Florida II es la segunda torre (Torre B) del conjunto Eco Florida en Froilán Roa 1201, La Florida, a pasos de la estación Vicuña Mackenna (L4/L4A) y cerca de Bellavista de La Florida (L5). Comparte el entorno de Mall Plaza Vespucio, supermercados y servicios, con muy buena conectividad hacia el centro y el sector oriente.","Edificio de 23 pisos en venta en verde con studios, 1D1B y 2D2B (en la ficha oficial solo se publican plantas de studio de 28,97 a 32 m²). Espacios comunes diseñados por Enrique Concha & Co.: cowork, BBQ panorámico, piscina al aire libre, jardín interior, fitness, lounge TV, espacio gourmet, pet zone y centro de lavado."}', '[["Dirección","Froilán Roa 1201, La Florida"],["Tipologías","Studio · 1D1B · 2D2B"],["Superficie","28,97 a 32 m² (studios publicados)"],["Metro","Vicuña Mackenna (L4/L4A) y Bellavista de La Florida (L5)"],["Amenities","Piscina · Cowork · Fitness · BBQ · Pet zone · Lounge TV"],["Entrega","Entrega futura, término estimado de obra 2027"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-florida-ii-1.webp","alt":"Render fachada Eco Florida II, La Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-florida-ii-2.webp","alt":"Render piscina Eco Florida II Torre B"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-la-florida/eco-florida-ii-2/', '{"imobu","mdiaz"}', false, false, 1),
  ('eco-valdes-i', 'Eco Valdés I', 'Fundamenta', 'La Florida', 2162, 'inmediata', '{0,1,2}', '30 a 52 m²', '', 'Edificio de 8 pisos en el centro de La Florida, junto a Metro Vicuña Mackenna y Vicente Valdés, con piscina y cowork.', '{"Eco Valdés I está en Vicente Valdés 615, en la zona más céntrica de La Florida, a pasos de las estaciones Vicuña Mackenna y Vicente Valdés (L4 y L5). Su entorno incluye Mall Plaza Vespucio, Florida Center, supermercados, clínicas y abundante transporte de superficie, con alta demanda de arriendo.","Edificio de 8 pisos con studios, 1D1B y 2D1B de 30 a 52 m², terminaciones Diseño Más y sello Sustentabilidad Más (LED con sensores, reciclaje, bicicletero). Espacios comunes: piscina en primer piso, quinchos, salón gourmet, fitness zone, cowork, lounge TV, pet zone y salón de lavado. Pie en hasta 48 cuotas."}', '[["Dirección","Vicente Valdés 615, La Florida"],["Tipologías","Studio · 1D1B · 2D1B"],["Superficie","30 a 52 m²"],["Metro","Vicuña Mackenna y Vicente Valdés (L4/L5)"],["Amenities","Piscina · Quinchos · Salón gourmet · Fitness · Cowork · Pet zone"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-valdes-i-1.webp","alt":"Fachada Eco Valdés I, La Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-valdes-i-2.webp","alt":"Piscina Eco Valdés I"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-valdes-i-3.webp","alt":"Fachada Eco Valdés I"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-la-florida/eco-valdes-i/', '{"imobu","mdiaz"}', false, false, 2),
  ('eco-valdes-ii', 'Eco Valdés II', 'Fundamenta', 'La Florida', 2247, 'inmediata', '{0,1,2}', '30 a 57 m²', '', 'Conjunto de 8 pisos a pasos de Metro Vicente Valdés con piscina, pista de trote y quinchos; entrega inmediata.', '{"Eco Valdés II se emplaza en Gerónimo de Alderete 396, La Florida, a pasos de la estación Vicente Valdés (L4 y L5) sobre Av. Vicuña Mackenna, con acceso directo a Mall Plaza Vespucio, Florida Center, comercio y servicios. Es una zona consolidada de alta demanda de arriendo por su conectividad.","Proyecto de 8 pisos en dos etapas (ambas con entrega inmediata) con studios, 1D1B, 2D1B y 2D2B de 30 a 57 m², terminaciones Diseño Más (mesón de granito, piso fotolaminado, ventanas PVC). Espacios comunes: piscina al aire libre, pista de trote, quinchos, pet zone, cowork, salón gourmet, fitness zone, lounge TV y salón de lavado."}', '[["Dirección","Gerónimo de Alderete 396, La Florida"],["Tipologías","Studio · 1D1B · 2D1B · 2D2B"],["Superficie","30 a 57 m²"],["Metro","Vicente Valdés (L4/L5)"],["Amenities","Piscina · Pista de trote · Quinchos · Cowork · Fitness · Pet zone"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-valdes-ii-1.webp","alt":"Fachada Eco Valdés II, La Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-valdes-ii-2.webp","alt":"Eco Valdés II etapa 1"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-valdes-ii-3.webp","alt":"Piscina Eco Valdés II"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-la-florida/eco-valdes-ii-etapa-ii/', '{"imobu","mdiaz"}', false, false, 3),
  ('eco-quilin', 'Eco Quilín I', 'Fundamenta', 'Macul', 2697, 'inmediata', '{0,2,3}', '34 a 83 m²', '', 'Torre de 17 pisos en Macul, a pasos de Av. Quilín y la futura estación Quilín de la Línea 8; studios, 2D y 3D.', '{"Eco Quilín I se ubica en Exequiel Fernández 3858, Macul, cerca de Av. Quilín y Av. Macul, de la estación Quilín (L4) y de la futura estación Quilín de la Línea 8. Zona residencial con universidades, comercio y rápido acceso a Américo Vespucio y al sector oriente.","Edificio de 17 pisos con studios, 2D2B y 3D2B de 34 a 83 m², porcelanato en todo el departamento, termopanel con marco PVC, mesón de granito y calefacción eléctrica. Espacios comunes: piscina al aire libre, cowork, lounge panorámico, BBQ panorámico, kids zone, fitness, salón gourmet, hall de doble altura y centro de lavado."}', '[["Dirección","Exequiel Fernández 3858, Macul"],["Tipologías","Studio · 2D2B · 3D2B"],["Superficie","34 a 83 m²"],["Metro","Quilín y Macul (L4); futura estación Quilín (L8)"],["Amenities","Piscina · Lounge panorámico · Cowork · Kids zone · Fitness · BBQ"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-quilin-1.webp","alt":"Fachada Eco Quilín I, Macul"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-quilin-2.webp","alt":"Piscina Eco Quilín I"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-macul/eco-quilin-i/', '{"imobu","mdiaz"}', false, false, 4),
  ('eco-quilin-ii', 'Eco Quilín II', 'Fundamenta', 'Macul', 3516, 'futura', '{1,2,3}', '40 a 97 m²', '', 'Segunda torre de Eco Quilín: 18 pisos en Macul con 1, 2 y 3 dormitorios junto a la futura estación Quilín de la Línea 8.', '{"Eco Quilín II está en Exequiel Fernández 3774, Macul, a metros de Eco Quilín I, cerca de Av. Quilín, de las estaciones Quilín y Macul (L4) y de la futura estación Quilín de la Línea 8. Entorno universitario y residencial con comercio, áreas verdes y buen acceso vial.","Torre de 18 pisos con departamentos de 1D1B, 2D2B y 3D2B de 40 a 97 m², porcelanato en todo el departamento, mesón de granito, termopanel PVC y calefacción eléctrica. Espacios comunes: BBQ panorámico, salón gourmet, piscina al aire libre, cowork, kids zone, fitness, lounge TV y centro de lavado."}', '[["Dirección","Exequiel Fernández 3774, Macul"],["Tipologías","1D1B · 2D2B · 3D2B"],["Superficie","40 a 97 m²"],["Metro","Quilín y Macul (L4); futura estación Quilín (L8)"],["Amenities","Piscina · BBQ panorámico · Cowork · Kids zone · Fitness"],["Entrega","Entrega futura"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-quilin-ii-1.webp","alt":"Render Eco Quilín II, Macul"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-quilin-ii-2.webp","alt":"Render piscina Eco Quilín II"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-macul/eco-quilin-ii/', '{"imobu","mdiaz"}', false, false, 5),
  ('eco-cerrillos', 'Eco Cerrillos', 'Fundamenta', 'Cerrillos', 2110, 'inmediata', '{0,1,2}', '32 a 61 m²', '', 'Torre de 21 pisos a pasos de Metro Cerrillos (L6), de studio a 2D2B, con piscina y lounge panorámico.', '{"Eco Cerrillos se ubica en Av. Departamental 3175, a pasos de la estación Cerrillos de la Línea 6, con acceso rápido a Av. Pedro Aguirre Cerda, Mall Plaza Oeste y el Parque Bicentenario de Cerrillos. Comuna en consolidación con precios de entrada bajos y buena conectividad al centro.","Edificio de 21 pisos con studios, 1D1B, 2D1B y 2D2B de 32 a 61 m², piso fotolaminado, mesón de granito y calefacción eléctrica. Espacios comunes: hall de doble altura, cowork, fitness, lounge TV, espacio gourmet, piscina al aire libre, BBQ panorámico, lounge panorámico y centro de lavado."}', '[["Dirección","Av. Departamental 3175, Cerrillos"],["Tipologías","Studio · 1D1B · 2D1B · 2D2B"],["Superficie","32 a 61 m²"],["Metro","Cerrillos (L6)"],["Amenities","Piscina · Lounge panorámico · BBQ · Cowork · Fitness · Gourmet"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-cerrillos-1.webp","alt":"Fachada Eco Cerrillos"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-cerrillos-2.webp","alt":"Piscina Eco Cerrillos"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-cerrillos/eco-cerrillos/', '{"imobu","mdiaz"}', false, false, 6),
  ('eco-egana', 'Eco Egaña', 'Fundamenta', 'Ñuñoa', 3635, 'futura', '{0,1,2}', '32 a 71 m²', 'Pronta entrega', 'Megaproyecto mixto sobre Metro Plaza Egaña (L3/L4): tres edificios con piscina, running track y placa comercial.', '{"Eco Egaña (Egaña Comunidad Sustentable) se levanta en la intersección de Av. Américo Vespucio e Irarrázaval, frente a Plaza Egaña y con acceso directo a la estación Plaza Egaña (Líneas 3 y 4). Junto a Mall Plaza Egaña y el futuro Espacio Egaña (oficinas y comercio), es uno de los nodos de mayor conectividad del sector oriente, ideal para renta corta y larga.","Tres edificios residenciales (Oriente, Poniente y Norte) con studios, 1D1B, 2D1B y 2D2B de 32 a 71 m², interiorismo de Enrique Concha & Co. y cocinas con cuarzo, termopanel PVC y USB. Espacios comunes: piscina, pista de running, salón gourmet, BBQ panorámico, cowork, más de 9.000 m² de áreas verdes y lounge panorámico con fogón."}', '[["Dirección","Av. Américo Vespucio 71, esq. Irarrázaval, Ñuñoa"],["Tipologías","Studio · 1D1B · 2D1B · 2D2B"],["Superficie","32 a 71 m²"],["Metro","Plaza Egaña (L3/L4), acceso directo"],["Amenities","Piscina · Running track · Cowork · BBQ · Lounge con fogón · Placa comercial"],["Entrega","Edificio Oriente 2026-2027; Poniente y Norte 2027"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-egana-1.webp","alt":"Render Eco Egaña Oriente, Plaza Egaña"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-egana-2.webp","alt":"Render placa comercial Eco Egaña"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-egana-3.webp","alt":"Render piscina y circuito de trote Eco Egaña"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-nunoa/eco-egana-oriente/', '{"imobu","mdiaz"}', false, false, 7),
  ('eco-espana', 'Eco España', 'Fundamenta', 'Santiago Centro', 2341, 'inmediata', '{0,1,2}', '28 a 62 m²', '', 'Edificio boutique de 9 pisos en Barrio República, entre Metro República (L1) y Toesca (L2), con piscina en azotea.', '{"Eco España está en Domeyko 2505, Barrio República, Santiago Centro, a pasos de las estaciones República (L1), Toesca (L2) y Unión Latinoamericana. Barrio histórico y universitario con alta demanda de arriendo estudiantil y profesional, cercano a la Alameda y al centro cívico.","Edificio de 9 pisos con studios, 1D1B, 2D1B y 2D2B de 28 a 62 m², porcelanato en todo el departamento, mesón de granito y radiadores eléctricos, con espacios comunes de Enrique Concha & Co.: piscina en azotea, lounge panorámico, BBQ, salón gourmet, cowork, fitness, lounge TV, áreas verdes y centro de lavado."}', '[["Dirección","Domeyko 2505, Santiago Centro (Barrio República)"],["Tipologías","Studio · 1D1B · 2D1B · 2D2B"],["Superficie","28 a 62 m²"],["Metro","República (L1) y Toesca (L2)"],["Amenities","Piscina en azotea · BBQ panorámico · Cowork · Fitness · Salón gourmet"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-espana-1.webp","alt":"Fachada Eco España, Barrio República"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-espana-2.webp","alt":"Piscina en azotea Eco España"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-santiago/eco-espana/', '{"imobu","mdiaz"}', false, false, 8),
  ('eco-estacion', 'Eco Estación', 'Fundamenta', 'Estación Central', 1868, 'inmediata', '{0,1,2}', '31 a 63 m²', '', 'Torre de 30 pisos a pasos de la Alameda y Metro San Alberto Hurtado (L1): el precio de entrada más bajo de Fundamenta.', '{"Eco Estación se ubica en Placilla 65, Estación Central, a pasos de la Alameda y de la estación San Alberto Hurtado (L1), frente al campus de la USACH y cerca de Estación Central y los terminales de buses. Zona de alta demanda de arriendo por estudiantes y trabajadores.","Torre de 30 pisos con studios, 1D, 2D1B y 2D2B de 31 a 63 m², mesón de granito, vitrocerámica, piso fotolaminado y radiadores eléctricos; sello sustentable con paneles fotovoltaicos y LED con sensores. Espacios comunes: piscina, fitness, BBQ, salón gourmet, lounge panorámico y centro de lavado."}', '[["Dirección","Placilla 65, Estación Central"],["Tipologías","Studio · 1D1B · 2D1B · 2D2B"],["Superficie","31 a 63 m²"],["Metro","San Alberto Hurtado (L1)"],["Amenities","Piscina · Fitness · BBQ · Salón gourmet · Lounge panorámico"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-estacion-1.webp","alt":"Fachada Eco Estación, Estación Central"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/eco-estacion-2.webp","alt":"Piscina Eco Estación"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/departamento-en-estacion-central/eco-estacion/', '{"imobu","mdiaz"}', false, false, 9),
  ('laguna-andina', 'Laguna Andina', 'Fundamenta', 'Lo Barnechea', 10483, 'futura', '{2,3}', '76 a 139 m²', 'Entrega 2028', 'Solo 69 departamentos de 2 y 3 dormitorios frente a la laguna en Los Trapenses, con piscina, gimnasio y senderos.', '{"Laguna Andina se emplaza en Av. Panorámica Norte 10750, sector Los Trapenses, Lo Barnechea, junto a la laguna y al parque Valle La Dehesa, con acceso por Pie Andino y Las Hualtatas. Entorno de baja densidad con colegios, comercio de Los Trapenses y rápida salida a Av. La Dehesa y a los centros de ski.","Tres edificios de cinco pisos con solo 69 departamentos de 2D2B, 3D2B y 3D3B con estar (76 a 139 m²), diseñados por Enrique Concha y Teresa Leighton, con termopanel PVC, cuarzo en cocina, porcelanato y USB-C. Espacios comunes: piscina al aire libre, gimnasio, salón gourmet, taller de bicicletas, senderos y áreas verdes."}', '[["Dirección","Av. Panorámica Norte 10750, Lo Barnechea (Los Trapenses)"],["Tipologías","2D2B · 3D2B · 3D3B + estar"],["Superficie","76 a 139 m²"],["Entorno","Laguna y parque Valle La Dehesa, Los Trapenses"],["Amenities","Piscina · Gimnasio · Salón gourmet · Taller de bicicletas · Senderos"],["Entrega","Entrega futura, fin de obra 2028"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/laguna-andina-1.webp","alt":"Render Laguna Andina, Lo Barnechea"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/laguna-andina-2.webp","alt":"Render exterior Laguna Andina"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/laguna-andina-3.webp","alt":"Render interior departamento Laguna Andina"}]'::jsonb, 'https://www.fundamenta.cl/proyectos-en-venta/lo-barnechea/laguna-andina/', '{"imobu","mdiaz"}', false, false, 10),
  ('pintor-cicarelli-i', 'Pintor Cicarelli I', 'Maestra', 'San Joaquín', 2908, 'inmediata', '{2,3}', '38 a 48 m²', '', 'Torre terminada a pasos de Metro Rodrigo de Araya: 2D y 3D desde 38 m² con piscina, quincho y conserjería 24 h.', '{"Ubicado en Pintor Cicarelli 288, San Joaquín, junto a Av. Vicuña Mackenna y a pocas cuadras de la estación Rodrigo de Araya (Línea 5). El sector concentra universidades, comercio y conectividad directa al centro y oriente de Santiago, lo que sostiene una fuerte demanda de arriendo.","Edificio de entrega inmediata con departamentos de 2D1B (38,06 m² útiles), 2DG1B (43,99 m²), 2D2B tipo mariposa (43,81 m²) y 3D1B (47,34 m²). Incluye cocina amoblada, cortinas roller, walk-in closet, termopanel y baños con conexión para lavadora; áreas comunes con piscina, quincho, lavandería, sala multiuso, bicicletero y conserjería 24 horas."}', '[["Dirección","Pintor Cicarelli 288, San Joaquín"],["Tipologías","2D1B · 2DG1B · 2D2B · 3D1B"],["Superficie","38 a 48 m² útiles"],["Metro","Rodrigo de Araya (L5)"],["Amenities","Piscina · Quincho · Lavandería · Sala multiuso · Conserjería 24 h"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/pintor-cicarelli-i-1.webp","alt":"Fachada edificio Pintor Cicarelli I, San Joaquín"}]'::jsonb, 'https://maestra.cl/proyectos/pintor-cicarelli-i/', '{"imobu","mdiaz"}', false, false, 11),
  ('pintor-cicarelli-ii', 'Pintor Cicarelli II', 'Maestra', 'San Joaquín', 2732, 'inmediata', '{1,2,3}', '33 a 47 m²', '', '1D a 3D desde 33 m² en barrio universitario de San Joaquín, a pasos de Metro Rodrigo de Araya; entrega inmediata.', '{"Segunda etapa del complejo Pintor Cicarelli en San Joaquín, a pocas cuadras de Av. Vicuña Mackenna y de la estación Rodrigo de Araya (Línea 5). Entorno con universidades, servicios y acceso rápido al centro, ideal para arriendo a estudiantes y jóvenes profesionales.","Departamentos de 1D1B (32,53 m² útiles), 2D1B (38,06 m²), 2DG1B (44,67 m²) y 3D1B (47,34 m²) con cocina amoblada, cortinas roller, walk-in closet, aislación EIFS y termopanel. Áreas comunes con piscina, quincho, lavandería, sala multiuso, juegos infantiles, bicicletero y acceso controlado."}', '[["Dirección","Pintor Cicarelli 278, San Joaquín"],["Tipologías","1D1B · 2D1B · 2DG1B · 3D1B"],["Superficie","33 a 47 m² útiles"],["Metro","Rodrigo de Araya (L5)"],["Amenities","Piscina · Quincho · Lavandería · Sala multiuso · Bicicletero"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/pintor-cicarelli-ii-1.webp","alt":"Render fachada Pintor Cicarelli II, San Joaquín"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/pintor-cicarelli-ii-2.webp","alt":"Galería Pintor Cicarelli II"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/pintor-cicarelli-ii-3.webp","alt":"Fachada Pintor Cicarelli II"}]'::jsonb, 'https://maestra.cl/proyectos/pintor-cicarelli-ii/', '{"imobu","mdiaz"}', false, false, 12),
  ('alto-buzeta', 'Alto Buzeta', 'Maestra', 'Cerrillos', 2091, 'inmediata', '{0,1,2,3}', '24 a 48 m²', '', 'Torre de 23 pisos en Cerrillos a 4 cuadras del Metro: studios desde 24 m² y 1D a 3D, el ticket más bajo de Maestra en Santiago.', '{"En Avenida Cinco 2951, Cerrillos, a cuatro cuadras de la estación Cerrillos (Línea 6, 20 minutos a Providencia), a dos cuadras de Plaza Buzeta y cerca del Parque Bicentenario, con acceso a Autopista Central y Autopista del Sol. Cerrillos es uno de los polos de desarrollo inmobiliario de mayor crecimiento en Santiago.","Edificio de 23 pisos y 273 departamentos: studio (24 m²), studio G (29,8 m²), 1D1B (32,8 m²), 2D1B (37,2 m²), 2DG1B (46,9 m²) y 3D1B (47,7 m²). Cocina amoblada, cortinas roller, walk-in closet, EIFS y termopanel; áreas comunes con quincho, lavandería, sala multiuso, juegos infantiles, bicicletero, áreas verdes y conserjería 24 h."}', '[["Dirección","Avenida Cinco 2951, Cerrillos"],["Tipologías","Studio · 1D1B · 2D1B · 2DG1B · 3D1B"],["Superficie","24 a 48 m² útiles"],["Metro","Cerrillos (L6), a 4 cuadras"],["Entorno","Parque Bicentenario · Plaza Buzeta · Autopista Central"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/alto-buzeta-1.webp","alt":"Render fachada Alto Buzeta, Cerrillos"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/alto-buzeta-2.webp","alt":"Render Alto Buzeta, Cerrillos"}]'::jsonb, 'https://maestra.cl/proyectos/alto-buzeta/', '{"imobu","mdiaz"}', false, false, 13),
  ('jardines-de-alvarado', 'Jardines de Alvarado', 'Maestra', 'Independencia', 2371, 'inmediata', '{1,2,3}', '32 a 48 m²', '', '1D a 3D desde 32 m² en Independencia, a pasos de Metro Plaza Chacabuco, con piscina y quincho.', '{"En Coronel Alvarado 2505, Independencia, cercano a las estaciones Plaza Chacabuco y Conchalí (Línea 3), Av. Vivaceta y Autopista Central. A minutos del centro de Santiago, en una comuna con alta demanda de arriendo por su conectividad y cercanía a hospitales y universidades.","Edificio terminado de 11 pisos con 1D1B (32,5 m² útiles), 2D1B (38,4 m²), 2DG1B (43,95 m²) y 3D1B (47,7 m²). Cocina amoblada con empotrados, cortinas roller, walk-in closet, EIFS y termopanel; áreas comunes con piscina, quincho, lavandería, sala multiuso, juegos infantiles, bicicletero, áreas verdes y conserjería 24 horas."}', '[["Dirección","Coronel Alvarado 2505, Independencia"],["Tipologías","1D1B · 2D1B · 2DG1B · 3D1B"],["Superficie","32 a 48 m² útiles"],["Metro","Plaza Chacabuco (L3)"],["Amenities","Piscina · Quincho · Lavandería · Sala multiuso · Conserjería 24 h"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/jardines-de-alvarado-1.webp","alt":"Fachada Jardines de Alvarado, Independencia"}]'::jsonb, 'https://maestra.cl/proyectos/jardines-de-alvarado/', '{"imobu","mdiaz"}', false, false, 14),
  ('mirador-mapocho', 'Mirador Mapocho', 'Maestra', 'Quinta Normal', 2556, 'inmediata', '{1,2,3}', '33 a 47 m²', '', '1D a 3D con piscina en Quinta Normal, junto a General Velásquez y a 800 m de Metro Gruta de Lourdes.', '{"En Mapocho 3951, Quinta Normal, a unos 800 m de la estación Gruta de Lourdes (Línea 5) y junto a la autopista General Velásquez, con conexión rápida al centro y al Hospital San Juan de Dios. Sector consolidado con colegios, comercio y parques ribereños.","Departamentos de 1D1B (32,5 m² útiles), 2DG1B (44,3 m²), 2D2B mariposa (43,8 m²) y 3D1B (47,3 m²). Cocina amoblada, cortinas roller, walk-in closet, EIFS y termopanel; áreas comunes con piscina, quincho, lavandería, sala multiuso, juegos infantiles, bicicletero, áreas verdes y conserjería 24 horas."}', '[["Dirección","Mapocho 3951, Quinta Normal"],["Tipologías","1D1B · 2D1B · 2D2B · 3D1B"],["Superficie","33 a 47 m² útiles"],["Metro","Gruta de Lourdes (L5)"],["Amenities","Piscina · Quincho · Lavandería · Sala multiuso · Conserjería 24 h"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/mirador-mapocho-1.webp","alt":"Fachada Mirador Mapocho, Quinta Normal"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/mirador-mapocho-2.webp","alt":"Banner Mirador Mapocho, Quinta Normal"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/mirador-mapocho-3.webp","alt":"Render Mirador Mapocho"}]'::jsonb, 'https://maestra.cl/proyectos/mirador-mapocho/', '{"imobu","mdiaz"}', false, false, 15),
  ('plaza-quilicura', 'Plaza Quilicura', 'Maestra', 'Quilicura', 2592, 'inmediata', '{2,3}', '38 a 47 m²', '', '2D y 3D con piscina sobre Américo Vespucio, Quilicura, frente a la futura estación de Metro Línea 7; entrega inmediata.', '{"En Av. Américo Vespucio 1456, Quilicura, a un paso del anillo Américo Vespucio y de la futura estación Plaza de Armas Quilicura (Línea 7, en construcción), con acceso directo a Autopista Central y Ruta 5. Comuna con fuerte polo industrial y logístico que impulsa la demanda de arriendo.","Edificio terminado con 2D1B (38 m² útiles), 2DG1B (43,95 m², agotada) y 3D1B (47,3 m²). Cocina amoblada, cortinas roller, walk-in closet, EIFS y termopanel; áreas comunes con piscina, quincho, lavandería, sala multiuso, juegos infantiles, acceso controlado y conserjería 24 horas."}', '[["Dirección","Av. Américo Vespucio 1456, Quilicura"],["Tipologías","2D1B · 2DG1B · 3D1B"],["Superficie","38 a 47 m² útiles"],["Metro","Futura estación Plaza de Armas Quilicura (L7)"],["Amenities","Piscina · Quincho · Lavandería · Sala multiuso · Conserjería 24 h"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/plaza-quilicura-1.webp","alt":"Fachada Plaza Quilicura"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/plaza-quilicura-2.webp","alt":"Render Plaza Quilicura"}]'::jsonb, 'https://maestra.cl/proyectos/plaza-quilicura/', '{"imobu","mdiaz"}', false, false, 16),
  ('teatinos-727', 'Teatinos 727', 'Monteclaro', 'Santiago Centro', 2858, 'inmediata', '{0,1,2}', '27 a 56 m²', '', 'Studios, 1D y 2D en pleno Barrio Cívico, a menos de 5 minutos de las líneas 1, 2, 3 y 5 del Metro; gimnasio, cowork y quinchos en azotea.', '{"Edificio en Teatinos 727, Santiago Centro, a pasos de Plaza de Armas, La Moneda, Cal y Canto y Santa Ana: acceso caminando a las líneas 1, 2, 3 y 5 del Metro y futura Línea 7. Entorno cívico y cultural con Parque Forestal, Museo de Bellas Artes, barrios Yungay y Brasil, ideal para arriendo a profesionales y estudiantes.","Estudios, 1D1B, 2D1B y 2D2B con cocina full electric, iluminación LED, termopanel, piso de alta resistencia y closet para lavadora en tipologías seleccionadas. Lobby de doble altura, coffee lounge, cowork, gimnasio, quinchos en azotea con vista, lavandería, bicicleteros, jardín interior, acceso controlado y CCTV."}', '[["Dirección","Teatinos 727, Santiago Centro"],["Tipologías","Studio · 1D1B · 2D1B · 2D2B"],["Superficie","Studio hasta 40,6 m² · 1D hasta 44,6 m² · 2D2B hasta 55,6 m² (totales aprox.)"],["Metro","Plaza de Armas (L3/L5) · Santa Ana (L2/L5) · Cal y Canto (L2/L3)"],["Amenities","Gimnasio · Cowork · Coffee lounge · Quinchos · Lavandería · Jardín interior"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/teatinos-727-1.webp","alt":"Render fachada Edificio Teatinos 727, Santiago Centro"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/teatinos-727-2.webp","alt":"Render acceso Edificio Teatinos 727"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/teatinos-727-3.webp","alt":"Fotografía del edificio Teatinos construido, Santiago Centro"}]'::jsonb, 'https://www.imonteclaro.cl/teatinos', '{"imobu","mdiaz"}', false, false, 17),
  ('nexus-vespucio', 'Nexus Vespucio', 'Costa Pacífico', 'La Cisterna', 2100, 'inmediata', '{1,2,3}', '28 a 60 m²', '', 'Departamentos de 1 a 3 dormitorios a una cuadra del Metro Intermodal La Cisterna, con entrega inmediata.', '{"Edificio Nexus Vespucio está en Av. Américo Vespucio 231, La Cisterna, a una cuadra de la estación Intermodal La Cisterna (Líneas 2 y 4A) y del eje Gran Avenida. Conecta en pocos minutos con el centro de Santiago y con la Autopista Vespucio Sur, en un entorno con comercio, colegios y áreas verdes.","Torre de 12 pisos con departamentos de 1, 2 y 3 dormitorios. Áreas comunes con sala de cowork, piscina, gimnasio, sala multiuso, quincho y terraza en primer piso, más salón de eventos y terraza panorámica en el último piso. Entrega inmediata y aplica a subsidio a la tasa según la inmobiliaria."}', '[["Dirección","Av. Américo Vespucio 231, La Cisterna"],["Tipologías","1D1B · 2D2B · 3D2B"],["Superficie","28 a 60 m² útiles"],["Metro","Intermodal La Cisterna (L2/L4A), a 1 cuadra"],["Amenities","Cowork · Piscina · Gimnasio · Quincho · Salón de eventos en último piso"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/nexus-vespucio-1.webp","alt":"Fachada Edificio Nexus Vespucio, La Cisterna"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/nexus-vespucio-2.webp","alt":"Edificio Nexus Vespucio"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/nexus-vespucio-3.webp","alt":"Fachada Nexus Vespucio"}]'::jsonb, 'https://m.icostapacifico.cl/estate_property/edificio-nexus-vespucio/', '{"imobu","mdiaz"}', false, false, 18),
  ('limit-apartments', 'Limit Apartments', 'Santolaya', 'Macul', 2913, 'futura', '{1,2}', '35 a 67 m²', 'Próxima entrega', '1 y 2 dormitorios en Macul junto a la futura Línea 8 y Mall Paseo Quilín, con piscina, gimnasio y hasta 12% de descuento.', '{"Limit Apartments se ubica en Mayor Abe 3090, sector Las Dalias de Macul, con acceso directo a la Autopista Vespucio Sur y a pasos de la futura estación de la Línea 8 del Metro. El entorno suma Mall Paseo Quilín, supermercados y servicios.","Edificio con departamentos de 1 y 2 dormitorios (35 a 67 m²), con piscina, gimnasio, quinchos y salón multiuso con terraza. Promociones vigentes: descuento hasta 12%, arriendo garantizado por 2 años, pie en hasta 60 cuotas y apoyo al dividendo. Piloto disponible para visita."}', '[["Dirección","Mayor Abe 3090, Macul"],["Tipologías","1D1B · 2D2B"],["Superficie","35 a 67 m²"],["Metro","Futura Línea 8 (en construcción)"],["Amenities","Piscina · Gimnasio · Quinchos · Salón multiuso con terraza"],["Entrega","Próxima entrega"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/limit-apartments-1.webp","alt":"Render Edificio Limit Apartments, Macul"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/limit-apartments-2.webp","alt":"Fachada Limit Apartments"}]'::jsonb, 'https://www.santolaya.cl/proyecto/limit', '{"imobu","mdiaz"}', false, false, 19),
  ('neo-florida', 'Neoflorida 3', 'Santolaya', 'La Florida', 2697, 'inmediata', '{1,2,3}', '52 a 95 m²', '', 'Entrega inmediata en La Florida cerca de Metro Vicente Valdés: 1 a 3 dormitorios con piscina, gimnasio y hasta 23% de descuento.', '{"Edificio Neoflorida 3 está en Alonso de Ercilla 7698, La Florida, cerca de la estación Vicente Valdés (Líneas 4 y 5) y de los accesos a Vespucio Sur. El sector concentra comercio, centros de salud y servicios, con fuerte demanda de arriendo.","Departamentos de 1, 2 y 3 dormitorios con ventanas termopanel y barandas de cristal. Áreas comunes con sala gourmet, piscina, quinchos, cowork, gimnasio equipado y bicicleteros. Entrega inmediata, descuento hasta 23%, arriendo garantizado 2 años y pie en hasta 60 cuotas."}', '[["Dirección","Alonso de Ercilla 7698, La Florida"],["Tipologías","1D1B · 2D1B · 2D2B · 3D2B"],["Superficie","52 a 95,4 m²"],["Metro","Vicente Valdés (L4/L5)"],["Amenities","Piscina · Gimnasio · Sala gourmet · Cowork · Quinchos"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neo-florida-1.webp","alt":"Edificio Neoflorida 3, La Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neo-florida-2.webp","alt":"Fachada Edificio Neoflorida 3, foto aérea"}]'::jsonb, 'https://www.santolaya.cl/proyecto/neoflorida-3', '{"imobu","mdiaz"}', false, false, 20),
  ('ramon-cruz', 'Edificio Ramón Cruz', 'Valle Sur', 'Macul', 2990, 'inmediata', '{2,3}', '44 a 63 m²', '', '2 y 3 dormitorios con entrega inmediata y 0% pie a pasos de Metro Grecia, con piscina, gimnasio y 1.000 m² de áreas comunes.', '{"Edificio Ramón Cruz se ubica en Ramón Cruz Montt 2137, Macul, a pasos de la estación Grecia (Línea 4) y cerca de la futura Línea 8, Mall Paseo Quilín, el campus de la Universidad de Chile y la Autopista Vespucio Sur.","Torre de 12 pisos, 3 subterráneos y 212 departamentos de 2 y 3 dormitorios (44 a 63 m²). Cerca de 1.000 m² de espacios comunes: hall de doble altura, sala multiuso con terraza, gimnasio, sala de juegos, lavandería, 2 quinchos, piscina exterior y bicicletero. Entrega inmediata con opción de 0% pie."}', '[["Dirección","Ramón Cruz Montt 2137, Macul"],["Tipologías","2D1B · 2D2B · 3D2B"],["Superficie","44 a 63 m²"],["Metro","Grecia (L4)"],["Amenities","Piscina · Gimnasio · 2 quinchos · Sala de juegos · Lavandería"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/ramon-cruz-1.webp","alt":"Render Edificio Ramón Cruz, Macul"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/ramon-cruz-2.webp","alt":"Render Edificio Ramón Cruz, Valle Sur"}]'::jsonb, 'https://invs.cl/project/edificio-ramon-cruz/', '{"imobu","mdiaz"}', false, false, 21),
  ('briones-luco-0920', 'Briones Luco 0920', 'Valle Sur', 'La Cisterna', 1990, 'inmediata', '{1,2}', '34 a 51 m²', '', 'Con 0% pie y entrega inmediata, a pasos de Metro Lo Ovalle: piscina y gimnasio en la cubierta.', '{"Edificio Briones Luco 0920 está en La Cisterna, en el límite con San Miguel, a pasos del Metro e Intermodal Lo Ovalle (Línea 2) y cerca de Gran Avenida, la Autopista Central y el Mall Espacio Urbano Gran Avenida.","Torre de 12 pisos con 280 departamentos de 1 y 2 dormitorios (34 a 51 m²), ventanas PVC termopanel y cocina equipada. Áreas comunes en cubierta con piscina, quinchos y gimnasio con vistas panorámicas, además de cowork, salas multiuso, sala de juegos y bicicletero. Entrega inmediata y opción de 0% pie."}', '[["Dirección","Briones Luco 0920, La Cisterna"],["Tipologías","1D1B · 2D1B · 2D2B"],["Superficie","34 a 51 m²"],["Metro","Lo Ovalle (L2) e Intermodal Lo Ovalle"],["Amenities","Piscina y gimnasio en cubierta · Quinchos · Cowork · Sala de juegos"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/briones-luco-0920-1.webp","alt":"Render Edificio Briones Luco 0920, La Cisterna"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/briones-luco-0920-2.webp","alt":"Render Edificio Briones Luco 0920, Valle Sur"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/briones-luco-0920-3.webp","alt":"Fachada Briones Luco 0920"}]'::jsonb, 'https://invs.cl/project/edificio-briones-luco-0920/', '{"imobu","mdiaz"}', false, false, 22),
  ('puerta-la-florida', 'Puerta La Florida', 'Lucval', 'La Florida', 1920, 'inmediata', '{0,1}', '21 a 33 m²', '', 'Estudios y 1D frente a Mall Florida Center y a pasos del Metro Línea 5, listos para arrendar con arriendo garantizado.', '{"Puerta La Florida está en Av. Vicuña Mackenna Poniente 5860, frente al Mall Florida Center y a pasos de las estaciones Mirador y Pedrero de la Línea 5. Es uno de los ejes con mayor demanda de arriendo de La Florida, cerca de universidades, supermercados y el Museo Interactivo Mirador.","Edificio de 11 pisos con dos tipologías: estudio (20,6 m²) y 1 dormitorio 1 baño (32,5 m²). Cuenta con lavandería, quinchos, recepción y bicicleteros, y se amplían las áreas comunes con gimnasio, plaza, zona de juegos y pet spa. Entrega inmediata, pie en hasta 60 cuotas, arriendo garantizado y beneficio DFL-2."}', '[["Dirección","Av. Vicuña Mackenna Poniente 5860, La Florida"],["Tipologías","Studio · 1D1B"],["Superficie","20,6 a 32,5 m²"],["Metro","Mirador y Pedrero (L5)"],["Entorno","Frente a Mall Florida Center"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/puerta-la-florida-1.webp","alt":"Edificio Puerta La Florida, fachada"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/puerta-la-florida-2.webp","alt":"Fachada Puerta La Florida"}]'::jsonb, 'https://www.puertalaflorida.cl/', '{"imobu","mdiaz"}', false, false, 23),
  ('don-tomas', 'Don Tomás', 'Crescer', 'Conchalí', 1925, 'inmediata', '{0,1,2}', '22 a 35 m²', '', 'Studios, 1 y 2 dormitorios entre las estaciones Vivaceta y Conchalí (L3), a 3 estaciones del centro.', '{"Don Tomás está en Teniente Yávar 1733, Conchalí, entre las estaciones Vivaceta y Conchalí de la Línea 3 del Metro, a solo 3 estaciones del centro de Santiago. El entorno ofrece supermercados, restaurantes, farmacias y comercio a pasos.","Edificio de 8 pisos y 274 departamentos (estudio, 1D1B y 2D2B) con conexión para lavadora y estacionamientos subterráneos. Áreas comunes con gimnasio, sala multiuso, lavandería, lobby, salas de estudio, juegos infantiles, quincho, jardín y gran terraza en altura. Orientado a inversión para arriendo."}', '[["Dirección","Teniente Yávar 1733, Conchalí"],["Tipologías","Studio · 1D1B · 2D2B"],["Superficie","22 a 34,5 m²"],["Metro","Vivaceta y Conchalí (L3)"],["Amenities","Gimnasio · Quincho · Terraza en altura · Salas de estudio · Lavandería"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/don-tomas-1.webp","alt":"Render fachada Edificio Don Tomás, Conchalí"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/don-tomas-2.webp","alt":"Render departamento 2D2B Don Tomás"}]'::jsonb, 'https://www.crescer.cl/project/dontomas', '{"imobu","mdiaz"}', false, false, 24),
  ('don-rafael', 'Don Rafael', 'Crescer', 'Santiago Centro', 2160, 'inmediata', '{0,1,2}', '19 a 32 m²', '', 'Studios y 1D a 500 m del Metro Toesca, en pleno barrio universitario de Santiago Centro, con entrega inmediata.', '{"Don Rafael se ubica en Domeyko 1950, Santiago Centro, a 500 metros de la estación Toesca (Línea 2) y rodeado de universidades e institutos, supermercados, restaurantes y servicios, en un barrio de alta demanda de arriendo estudiantil.","Edificio de 9 pisos con 108 departamentos tipo studio, 1D1B y 2D1B, en armonía con el carácter histórico del sector. Áreas comunes con salas multiuso, lavandería, lobby, gimnasio, quincho, bicicletero, estacionamientos y gran terraza en altura. Entrega inmediata, pensado para inversión en arriendo."}', '[["Dirección","Domeyko 1950, Santiago Centro"],["Tipologías","Studio · 1D1B · 2D1B"],["Superficie","19 a 31,8 m²"],["Metro","Toesca (L2), a 500 m"],["Amenities","Gimnasio · Quincho · Terraza en altura · Salas multiuso · Lavandería"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/don-rafael-1.webp","alt":"Render fachada Edificio Don Rafael, Santiago Centro"}]'::jsonb, 'https://www.crescer.cl/project/donrafael', '{"imobu","mdiaz"}', false, false, 25),
  ('252-marathon', '252 Marathon', 'Surmonte', 'Ñuñoa', 3663, 'inmediata', '{1,2,3}', '41 a 82 m²', '', 'Edificio de autor estilo SoHo en Ñuñoa, frente a plaza y a pasos del Metro Rodrigo de Araya, con entrega inmediata y exención de IVA.', '{"Ubicado en Zañartu 1905, Ñuñoa, frente a una plaza y a pasos del Estadio Nacional, con acceso a Metro Rodrigo de Araya y Ñuble (Línea 5), ciclovías y transporte público. En el entorno están la Universidad Mayor, el Centro Médico Ñuñoa y el Parque Juan XXIII, un sector consolidado y de alta demanda de arriendo.","Torre de 14 pisos y 252 departamentos de 1, 2 y 3 dormitorios (41 a 82 m²), con diseño de T+AA inspirado en el SoHo neoyorquino: fachadas oscuras, fierro, madera y miradores. Certificado Efizity en eficiencia energética; cuenta con piscina, quinchos panorámicos, azoteas privadas, patio inglés, ascensores panorámicos y áreas verdes."}', '[["Dirección","Zañartu 1905, Ñuñoa"],["Tipologías","1D · 2D · 3D"],["Superficie","41 a 82 m²"],["Metro","Rodrigo de Araya y Ñuble (L5)"],["Amenities","Piscina · Quinchos panorámicos · Azoteas privadas · Patio inglés"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/252-marathon-1.webp","alt":"Render de la fachada de 252 Marathon, Ñuñoa"}]'::jsonb, 'https://surmonte.cl/proyecto/252marathon/', '{"imobu","mdiaz"}', false, false, 26),
  ('153-san-cristobal', '153 San Cristóbal', 'Surmonte', 'Independencia', 2000, 'inmediata', '{1,2,3}', '53 a 146 m²', '', 'Ticket de entrada bajo a pasos del Metro Hospitales (L3) y del Mall Barrio Independencia, con entrega inmediata.', '{"Se emplaza en Nueva San Cristóbal 1220, en un sector renovado de Independencia, a pasos de la estación Hospitales de la Línea 3 del Metro y de las principales avenidas. Cerca del Mall Barrio Independencia, la Clínica Dávila y los campus de la Universidad de Chile, con corredor de transporte público y ciclovías nuevas.","Edificio de 12 pisos y 153 departamentos de 1, 2 y 3 dormitorios, con superficies de 53 a 146 m² y unidades con jardín. Diseñado por Alvano y Riquelme Arquitectos, prioriza la luz natural y cuenta con piscina, quinchos panorámicos, salón multiuso, bicicleteros y áreas verdes."}', '[["Dirección","Nueva San Cristóbal 1220, Independencia"],["Tipologías","1D · 2D · 3D"],["Superficie","53 a 146 m²"],["Metro","Hospitales (L3)"],["Amenities","Piscina · Quinchos panorámicos · Salón multiuso · Bicicleteros"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/153-san-cristobal-1.webp","alt":"Render de la fachada de 153 San Cristóbal, Independencia"}]'::jsonb, 'https://surmonte.cl/proyecto/153sancristobal/', '{"imobu","mdiaz"}', false, false, 27),
  ('neohaus-la-dehesa', 'Neohaus La Dehesa', 'Neohaus', 'Lo Barnechea', 6718, 'inmediata', '{1,2}', '47 a 92 m²', '', 'Departamentos de 1 y 2 dormitorios con terminaciones premium en el corazón de La Dehesa, a 220 m del Portal La Dehesa.', '{"En el núcleo comercial de La Dehesa, Lo Barnechea, a 3 minutos a pie del Mall Portal La Dehesa, Clínica Santa María y Jumbo, y a menos de 1 km de colegios, strip centers y Espacio Urbano. Clínica Alemana queda a 1,3 km. Un sector de alta renta con demanda estable de arriendo ejecutivo.","Proyecto mixto con placa comercial y departamentos de 1D1B y 2D2B de 47 a 92 m², entregados con cocina equipada (horno, encimera vitrocerámica, microondas, refrigerador, lavavajillas), climatización split independiente, losa radiante en baños con mármol travertino y piso flotante. Áreas comunes con terraza panorámica, jacuzzi y sala de pool."}', '[["Dirección","Los Adobes 1650, La Dehesa, Lo Barnechea"],["Tipologías","1D1B · 2D2B"],["Superficie","47 a 92 m²"],["Entorno","Portal La Dehesa, Clínica Santa María y Jumbo a 220 m"],["Amenities","Terraza panorámica · Jacuzzi · Sala de pool · Placa comercial"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neohaus-la-dehesa-1.webp","alt":"Fachada nocturna de Neohaus La Dehesa"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neohaus-la-dehesa-2.webp","alt":"Fachada de Neohaus La Dehesa en Lo Barnechea"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neohaus-la-dehesa-3.webp","alt":"Living y dormitorio de un departamento piloto de Neohaus La Dehesa"}]'::jsonb, 'https://www.neohaus.cl/neohaus-la-dehesa-departamentos/', '{"imobu","mdiaz"}', false, false, 28),
  ('neohaus-vitacura', 'Neohaus Vitacura', 'Neohaus', 'Vitacura', 6515, 'inmediata', '{1,2}', '51 a 100 m²', '', 'Torre de 15 pisos en Av. Las Condes con piscina panorámica en la azotea, talleres home-office y placa comercial.', '{"Ubicado en Av. Las Condes 12.170, sector Tabancura, Vitacura, sobre uno de los ejes comerciales y de servicios más consolidados del sector oriente, con acceso directo a Av. Las Condes y a la conectividad vial hacia Las Condes, Lo Barnechea y el centro. El proyecto integra una plaza central con placa comercial.","Edificio de 15 pisos más terraza con departamentos de 1D1B y 2D2B de 51 a 100 m², 12 talleres multipropósito en venta y seis ascensores. En el piso 16: piscina panorámica con solárium, dos jacuzzis, cuatro quinchos con parrilla eléctrica, gimnasio, sala de pool, salón gourmet y sala multimedia climatizados, además de lavandería y hall de doble altura."}', '[["Dirección","Av. Las Condes 12170, Vitacura"],["Tipologías","1D1B · 2D2B"],["Superficie","51 a 100 m²"],["Entorno","Tabancura, Av. Las Condes, placa comercial propia"],["Amenities","Piscina panorámica · Jacuzzis · Quinchos · Gimnasio · Salón gourmet"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neohaus-vitacura-1.webp","alt":"Render de la torre Neohaus Vitacura"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neohaus-vitacura-2.webp","alt":"Render aéreo de Neohaus Vitacura y su placa comercial"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/neohaus-vitacura-3.webp","alt":"Fachada Neohaus Vitacura"}]'::jsonb, 'https://www.neohaus.cl/neohaus-vitacura/', '{"imobu","mdiaz"}', false, false, 29),
  ('nunoa-2024', 'Ñuñoa 2024', 'FDI', 'Ñuñoa', 2996, 'inmediata', '{1,2,3}', '37 a 66 m²', '', 'Departamentos de 1 a 3 dormitorios en Ñuñoa con rooftop, piscina y cowork, entrega inmediata y hasta 16% de descuento.', '{"Edificio Ñuñoa 2024 se ubica en Francisco de Paula 2024, en el sector de Rodrigo de Araya, Ñuñoa, a pocas cuadras de estaciones de metro, ciclovías, malls, supermercados y centros deportivos. Comuna con alta plusvalía y demanda sostenida de arriendo por su cercanía a universidades y al eje Vicuña Mackenna.","Cuatro tipologías de 1D1B, 2D2B y 3D2B de 37,3 a 65,8 m² totales, con porcelanato en todo el departamento, cocina amoblada con cubierta de granito y equipada, y ventanas termopanel de PVC. Áreas comunes: piscina, rooftop con quinchos, gourmet zone, cowork, gimnasio, kids zone, play zone, sala múltiple y acceso controlado 24 horas."}', '[["Dirección","Francisco de Paula 2024, Ñuñoa"],["Tipologías","1D1B · 2D2B · 3D2B"],["Superficie","37 a 66 m² totales"],["Entorno","Sector Rodrigo de Araya, a cuadras de metro, ciclovías y malls"],["Amenities","Piscina · Rooftop con quinchos · Cowork · Gimnasio · Kids zone"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/nunoa-2024-1.webp","alt":"Acceso y fachada del Edificio Ñuñoa 2024"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/nunoa-2024-2.webp","alt":"Rooftop con quinchos del Edificio Ñuñoa 2024"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/nunoa-2024-3.webp","alt":"Fachada Ñuñoa 2024"}]'::jsonb, 'https://nunoa2024.cl/', '{"imobu","mdiaz"}', false, false, 30),
  ('capitan-orella', 'Capitán Orella', 'FDI', 'Ñuñoa', 5810, 'inmediata', '{1,2}', '48 a 56 m²', '', 'Edificio boutique de 65 departamentos a una cuadra del Metro Ñuñoa y de Plaza Ñuñoa, con piscina y entrega inmediata.', '{"En Capitán Orella 2413, Ñuñoa, a pasos de Av. Pedro de Valdivia y a una cuadra de Av. Irarrázaval y la estación Ñuñoa del Metro (Líneas 3 y 6). Entorno de restaurantes y cervecerías de Plaza Ñuñoa y Plaza Pedro de Valdivia, con ciclovías por Antonio Varas, Simón Bolívar y Ricardo Lyon, Caracol Ñuñoa, bancos y supermercados.","Proyecto de escala reducida (65 departamentos) con tres tipologías: 1,5D1B de 48,33 m², 2D1B de 48,63 m² y 2D2B de 56,29 m² totales, todas con terraza. Áreas comunes con piscina, jardines y bicicletero. Beneficios vigentes: 10% de pie en hasta 36 cuotas, hasta 15% de descuento más bono UF 200 en 2 dormitorios y subsidio a la tasa."}', '[["Dirección","Capitán Orella 2413, Ñuñoa"],["Tipologías","1,5D1B · 2D1B · 2D2B"],["Superficie","48 a 56 m²"],["Metro","Ñuñoa (L3/L6), a una cuadra"],["Amenities","Piscina · Jardines · Bicicletero"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/capitan-orella-1.webp","alt":"Fachada del Edificio Capitán Orella en Ñuñoa"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/capitan-orella-2.webp","alt":"Fachada del Edificio Capitán Orella vista desde la calle"}]'::jsonb, 'https://www.capitanorella.cl/', '{"imobu","mdiaz"}', false, false, 31),
  ('stay', 'Stay', 'FDI', 'Las Condes', 6990, 'inmediata', '{2,3}', '68 a 234 m²', '', 'Departamentos con terraza panorámica en Las Condes, desde 2D2B de 68 m² hasta dúplex de 3D, con piscina y cowork.', '{"Ubicado en Mar del Sur 1111, sector Sebastián Elcano de Las Condes, un barrio residencial consolidado y tranquilo, con servicios, comercio y colegios a pasos, y buena conectividad hacia los ejes Apoquindo, Presidente Riesco y Américo Vespucio.","Edificio de departamentos de 2 y 3 dormitorios con terrazas panorámicas, de 68 a 234 m² totales, incluyendo dúplex de 3D con estar y terraza (157 y 212 m²). Áreas comunes: piscina, quincho con fogón, bike center, cowork, meeting point y hall de acceso. Sala de ventas y piloto en el edificio."}', '[["Dirección","Mar del Sur 1111, Las Condes"],["Tipologías","2D2B · 3D3B · Dúplex 3D4B"],["Superficie","68 a 234 m² totales"],["Entorno","Sector Sebastián Elcano, Las Condes"],["Amenities","Piscina · Quincho con fogón · Bike center · Cowork · Meeting point"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/stay-1.webp","alt":"Render de la fachada del Edificio Stay, Las Condes"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/stay-2.webp","alt":"Fachada Stay"}]'::jsonb, 'https://edificiostay.cl/', '{"imobu","mdiaz"}', false, false, 32),
  ('activa-wm815', 'Activa WM815', 'Activa', 'La Florida', 3181, 'inmediata', '{1,2,3}', '36 a 67 m²', '', 'Torre Design to Rent en Walker Martínez, a 1 km de Metro Vicuña Mackenna: 1 a 3 dormitorios con piscina, gimnasio y cowork.', '{"Activa WM815 se ubica en Av. Walker Martínez 815, en el sector Vicente Valdés de La Florida, un barrio consolidado con comercio, colegios y servicios a pasos. Está a unos 1.000 m de Metro Vicuña Mackenna (L4/L5) y a 1,3 km de Vicente Valdés y Bellavista de La Florida, con paraderos de buses a menos de 100 m.","Es un proyecto Design to Rent pensado para inversionistas: departamentos de 1, 2 y 3 dormitorios (35,7 a 66,7 m² útiles; 42 a 78 m² totales) con piso SPC, termopanel, cubierta de granito, cortinas roller y cerradura electrónica. El edificio tiene piscina, gimnasio y calistenia, sala de yoga, multicancha, salón gourmet, sala de eventos, cowork, quincho, lavandería, bicicletero y CCTV en todos los pisos."}', '[["Dirección","Av. Walker Martínez 815, La Florida"],["Tipologías","1D1B · 2D2B · 3D2B"],["Superficie","35,7 a 66,7 m² útiles (42 a 78 m² totales)"],["Metro","Vicuña Mackenna (L4/L5) a 1 km; Vicente Valdés y Bellavista de La Florida a 1,3 km"],["Amenities","Piscina · Gimnasio · Sala de yoga · Multicancha · Salón gourmet · Cowork · Quincho · Lavandería"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/activa-wm815-1.webp","alt":"Render de la fachada del edificio Activa WM815 en La Florida"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/activa-wm815-2.webp","alt":"Living comedor y cocina de departamento piloto Activa WM815"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/activa-wm815-3.webp","alt":"Terraza de departamento piloto Activa WM815"}]'::jsonb, 'https://www.activa.cl/proyecto-activa-wm-815/', '{"imobu","mdiaz"}', false, false, 33),
  ('activa-hipodromo-plaza', 'Activa Hipódromo Plaza', 'Activa', 'Independencia', 2753, 'inmediata', '{1,2,3}', '35 a 68 m²', '', 'Design to Rent junto a Plaza Chacabuco y Metro Línea 3: 1 a 3 dormitorios con piscina, gimnasio y cowork, listo para arrendar.', '{"Activa Hipódromo Plaza está en David Arellano 1954, en un barrio tradicional de Independencia al norte del Hipódromo Chile y a pasos de Plaza Chacabuco. Queda a unos 340 m de Metro Conchalí (L3) y a 1 km de Metro Plaza Chacabuco (L3), con paraderos de Av. Independencia y Fermín Vivaceta a 200 m.","Proyecto Design to Rent para inversionistas, con departamentos de 1, 2 y 3 dormitorios (34,8 a 67,8 m² útiles; 43 a 75 m² totales), piso SPC, ventanas PVC con termopanel, cubierta de granito, cortinas roller y cerradura electrónica. Cuenta con piscina, gimnasio, sala de yoga, sala de eventos, cowork, quincho, lavandería, juegos infantiles, bicicletero y CCTV en todos los pisos."}', '[["Dirección","David Arellano 1954, Independencia"],["Tipologías","1D1B · 2D2B · 3D2B"],["Superficie","34,8 a 67,8 m² útiles (43 a 75 m² totales)"],["Metro","Conchalí (L3) a 340 m; Plaza Chacabuco (L3) a 1 km"],["Amenities","Piscina · Gimnasio · Sala de yoga · Sala de eventos · Cowork · Quincho · Lavandería · Juegos infantiles"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/activa-hipodromo-plaza-1.webp","alt":"Piscina y fachada del edificio Activa Hipódromo Plaza en Independencia"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/activa-hipodromo-plaza-2.webp","alt":"Lobby del edificio Activa Hipódromo Plaza"}]'::jsonb, 'https://www.activa.cl/proyecto-activa-hipodromo-plaza/', '{"imobu","mdiaz"}', false, false, 34),
  ('euro-vicuna-mackenna-1432', 'Vicuña Mackenna 1432', 'Euro Inmobiliaria', 'Ñuñoa', 3381, 'inmediata', '{1,2}', '30 a 55 m²', '', 'Multifamily en Ñuñoa a 10 minutos de Metro Ñuble e Irarrázaval: 1D y 2D con piscina panorámica y 4 años de arriendo asegurado.', '{"Vicuña Mackenna 1432 está en Ñuñoa, en el eje de Av. Vicuña Mackenna, a unos 10 minutos a pie de Metro Ñuble (L5/L6) y de Metro Irarrázaval (L3/L5), con múltiples recorridos de buses. Cerca están Parque San Eugenio, Parque Bustamante, comercio y supermercados, además del Mall Vivo en construcción.","Edificio multifamily orientado a renta, con departamentos de 1D1B y 2D (1 o 2 baños) de 30 a 55 m² útiles (32 a 60 m² totales), porcelanato, ventanas PVC con termopanel, encimera vitrocerámica, horno eléctrico, iluminación LED, cortinas roller y alarma. Amenities: piscina panorámica, plaza interior, sala cowork, sala de niños y bicicletero; Euro ofrece 4 años de arriendo asegurado con administración gratis."}', '[["Dirección","Av. Vicuña Mackenna 1432, Ñuñoa"],["Tipologías","1D1B · 2D1B · 2D2B"],["Superficie","30 a 55 m² útiles (32 a 60 m² totales)"],["Metro","Ñuble (L5/L6) e Irarrázaval (L3/L5), 10 min a pie"],["Amenities","Piscina panorámica · Plaza interior · Cowork · Sala de niños · Bicicletero"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/euro-vicuna-mackenna-1432-1.webp","alt":"Render de la fachada del edificio Vicuña Mackenna 1432"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/euro-vicuna-mackenna-1432-2.webp","alt":"Living comedor con terraza de departamento piloto en Vicuña Mackenna 1432"}]'::jsonb, 'https://www.euroinmobiliaria.cl/proyectos/vicuna-mackenna-1432', '{"imobu","mdiaz"}', false, false, 35),
  ('euro-guillermo-mann-1401', 'Guillermo Mann 1401', 'Euro Inmobiliaria', 'Ñuñoa', 3461, 'inmediata', '{1,2}', '31 a 55 m²', '', 'Ñuñoa consolidado, a 13 minutos de Metro Ñuble y Rodrigo de Araya: 1D y 2D con piscina, cowork y 4 años de renta asegurada.', '{"Guillermo Mann 1401 se emplaza en Ñuñoa, sector Estadio Nacional, a unos 13 minutos a pie de Metro Ñuble (L5/L6) y de Metro Rodrigo de Araya (L5), con buses en el entorno. A menos de 2 km están el Estadio Nacional, parques y clubes deportivos, Av. Vicuña Mackenna con supermercados y comercio, y el futuro Mall Vivo.","Departamentos de 1D1B (31 m² útiles) y 2D2B (51 y 55 m² útiles), con piso vinílico SPC, ventanas PVC con termopanel, cubierta de granito, horno eléctrico, encimera vitrocerámica y alarma en la puerta principal. Áreas comunes: piscina, plaza exterior, sala cowork, sala de niños y bicicletero; Euro ofrece 4 años de arriendo asegurado con administración gratis."}', '[["Dirección","Guillermo Mann 1401, Ñuñoa"],["Tipologías","1D1B · 2D2B"],["Superficie","31 a 55 m² útiles (34 a 59 m² totales)"],["Metro","Ñuble (L5/L6) y Rodrigo de Araya (L5), 13 min a pie"],["Amenities","Piscina · Plaza exterior · Cowork · Sala de niños · Bicicletero"],["Entrega","Entrega inmediata"]]'::jsonb, '[{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/euro-guillermo-mann-1401-1.webp","alt":"Render de la fachada del edificio Guillermo Mann 1401"},{"src":"https://hpcmsufawcqigzxxrigt.supabase.co/storage/v1/object/public/proyectos/euro-guillermo-mann-1401-2.webp","alt":"Render interior de living comedor y cocina en Guillermo Mann 1401"}]'::jsonb, 'https://www.euroinmobiliaria.cl/proyectos/guillermo-mann-1401', '{"imobu","mdiaz"}', false, false, 36)
